    pd = globals().get('pd')
    if pd is None:
        import pandas as pd

    data = {
        'period_start': [r.get('period_start') for r in datasets[0]['rows']],
        'period_end': [r.get('period_end') for r in datasets[0]['rows']],
        'confirmed_revenue': [r.get('confirmed_revenue') for r in datasets[0]['rows']],
        'target_revenue': [r.get('target_revenue') for r in datasets[0]['rows']],
    }
    df = pd.DataFrame(data)

    for col in ['confirmed_revenue', 'target_revenue']:
        df[col] = pd.to_numeric(df[col], errors='coerce')

    results = []
    mask = df['target_revenue'].notna()
    if mask.any():
        df.loc[mask, 'completion_ratio_calc'] = (df.loc[mask, 'confirmed_revenue'] / df.loc[mask, 'target_revenue']) * 100
        for idx, row in df[mask].iterrows():
            period = f"{row['period_start']} to {row['period_end']}"
            results.append({
                'title': f'完成度: {row["completion_ratio_calc"]:.2f}%',
                'detail': f'{period} 销售额 {row["confirmed_revenue"]:.2f}，目标 {row["target_revenue"]:.2f}',
                'evidence': {'n': 1}
            })
    else:
        for idx, row in df.iterrows():
            period = f"{row['period_start']} to {row['period_end']}"
            results.append({
                'title': f'实际销售额: {row["confirmed_revenue"]:.2f}',
                'detail': f'{period} 已确认销售额为 {row["confirmed_revenue"]:.2f}，无对应销售目标数据',
                'evidence': {'n': 1}
            })
    return results
